    assert.strictEqual(subsList.querySelectorAll('script').length, 0, 'No script tags should be parsed');
    assert.strictEqual(subsList.querySelectorAll('svg').length, 0, 'No svg tags should be parsed');
    assert.strictEqual(subsList.querySelectorAll('details').length, 0, 'No details tags should be parsed');

    // Verify textContent has the exact string escaped safely
    const trackNames = Array.from(subsList.querySelectorAll('.track-name')).map(el => el.textContent);
    assert.ok(trackNames.some(t => t.includes('<img src="invalid" onerror="window._xss_pwned=true">English XSS')), 'Label must be escaped safely as literal text');

    window.PlayerController.destroy();
    window.PlayerOSDController.destroy();
  });

  await check('HOSTILE_SERVER_PAYLOADS', 'Hostile XSS server names in CLUSTER_SERVERS are safely handled via textContent', () => {
    const env = buildCleanEnv();
    const { window } = env;

    window._srv_pwned = false;

    window.CinejoyApp.init();
    window.CinejoyApp.switchView('player');
    window.PlayerController.init();
    window.PlayerOSDController.init();

    // We can test openServerModal with the default servers
    window.PlayerOSDController.openServerModal();

    const serverList = window.document.getElementById('player-server-list');
    const items = serverList.querySelectorAll('.modal-list-item');
    assert.ok(items.length >= 5, 'Server list must populate cluster servers');

    // Verify no script or unescaped elements
    assert.strictEqual(serverList.querySelectorAll('script').length, 0);

    window.PlayerController.destroy();
    window.PlayerOSDController.destroy();
  });

  await check('HOSTILE_ERROR_PAYLOADS', 'Hostile XSS in showError() title and message are rendered safely via textContent', () => {
    const env = buildCleanEnv();
    const { window } = env;

    window._err_pwned = false;

    window.CinejoyApp.init();
    window.CinejoyApp.switchView('player');
    window.PlayerController.init();
    window.PlayerOSDController.init();

    const xssTitle = '<img src=x onerror="window._err_pwned=true">Fatal Error';
    const xssMessage = '<script>window._err_pwned=true</script>The network stream was aborted: <svg onload="window._err_pwned=true">';

    window.PlayerOSDController.showError(xssTitle, xssMessage);

    assert.strictEqual(window._err_pwned, false, 'Error dialog XSS must NOT execute');

    const titleEl = window.document.getElementById('player-error-title');
    const msgEl = window.document.getElementById('player-error-message');

    assert.strictEqual(titleEl.textContent, xssTitle, 'Title textContent must match literal string');
    assert.strictEqual(msgEl.textContent, xssMessage, 'Message textContent must match literal string');
    assert.strictEqual(titleEl.querySelectorAll('img').length, 0);
    assert.strictEqual(msgEl.querySelectorAll('script').length, 0);

    window.PlayerController.destroy();
    window.PlayerOSDController.destroy();
  });

  await check('HOSTILE_BUFFERING_PAYLOADS', 'Hostile customText in setBuffering() is rendered safely via textContent', () => {
    const env = buildCleanEnv();
    const { window } = env;

    window._buf_pwned = false;

    window.CinejoyApp.init();
    window.CinejoyApp.switchView('player');
    window.PlayerController.init();
    window.PlayerOSDController.init();

    const hostileBufferingText = '<img src=x onerror="window._buf_pwned=true">Buffering segment #42...';
    window.PlayerOSDController.setBuffering(true, hostileBufferingText);

    assert.strictEqual(window._buf_pwned, false, 'Buffering XSS must NOT execute');
    const bufEl = window.document.getElementById('player-buffering-text');
    assert.strictEqual(bufEl.textContent, hostileBufferingText);
    assert.strictEqual(bufEl.querySelectorAll('img').length, 0);

    window.PlayerController.destroy();
    window.PlayerOSDController.destroy();
  });

  await check('HOSTILE_SEEK_TOAST_DELTA', 'showSeekFeedback handles dynamic seek delta, negative numbers, NaN, and string fuzzing', () => {
    const env = buildCleanEnv();
    const { window } = env;

    window.CinejoyApp.init();
    window.CinejoyApp.switchView('player');
    window.PlayerController.init();
    window.PlayerOSDController.init();

    const toastText = window.document.getElementById('player-feedback-text');

    // 1. Valid +15s
    window.PlayerOSDController.showSeekFeedback(true, 15);
    assert.strictEqual(toastText.textContent, 'Forward +15s');

    // 2. Valid -10s
    window.PlayerOSDController.showSeekFeedback(false, 10);
    assert.strictEqual(toastText.textContent, 'Rewind -10s');

    // 3. Fallback on undefined / NaN -> defaults to 15s
    window.PlayerOSDController.showSeekFeedback(true, NaN);
    assert.strictEqual(toastText.textContent, 'Forward +15s');

    window.PlayerOSDController.showSeekFeedback(false, "hostile_string");
    assert.strictEqual(toastText.textContent, 'Rewind -15s');

    window.PlayerOSDController.showSeekFeedback(true, -30);
    assert.strictEqual(toastText.textContent, 'Forward +15s');

    window.PlayerController.destroy();
    window.PlayerOSDController.destroy();
  });

  // ===========================================================================
  // SECTION 6: TIMELINE SCRUBBER & GOOGLE TV COUNTDOWN TYPOGRAPHY
  // ===========================================================================
  console.log(`\n${C.bold}${C.cyan}▶ SECTION 6: Timeline Scrubber & Google TV Countdown Typography${C.reset}`);

  await check('COUNTDOWN_REMAINING_DISPLAY', 'updateTimeline displays elapsed time and remaining countdown (-HH:MM:SS) in Google Sans tabular', () => {
    const env = buildCleanEnv();
    const { window } = env;

    window.CinejoyApp.init();
    window.CinejoyApp.switchView('player');
    window.PlayerController.init();
    window.PlayerOSDController.init();

    const curEl = window.document.getElementById('osd-current-time');
    const durEl = window.document.getElementById('osd-duration-time');

    // At 30m of a 2h movie (cur=1800, dur=7200) -> remaining should be 1h30m (-01:30:00)
    window.PlayerOSDController.updateTimeline(1800, 7200, 3600);

    assert.strictEqual(curEl.textContent, '00:30:00', 'Current time must be 00:30:00');
    assert.strictEqual(durEl.textContent, '-01:30:00', 'Duration time must display countdown remaining: -01:30:00');

    // At 1h59m of a 2h movie (cur=7140, dur=7200) -> remaining 1m0s (-00:01:00)
    window.PlayerOSDController.updateTimeline(7140, 7200, 7200);
    assert.strictEqual(curEl.textContent, '01:59:00');
    assert.strictEqual(durEl.textContent, '-00:01:00');

    // Zero / Infinite duration edge cases
    window.PlayerOSDController.updateTimeline(0, 0, 0);
    assert.strictEqual(curEl.textContent, '00:00:00');
    assert.strictEqual(durEl.textContent, '00:00:00');

    window.PlayerOSDController.updateTimeline(50, Infinity, 0);
    assert.strictEqual(curEl.textContent, '00:00:50');
    assert.strictEqual(durEl.textContent, '00:00:00');

    window.PlayerController.destroy();
    window.PlayerOSDController.destroy();
  });

  await check('SCRUBBER_EXPANDING_GEOMETRY', 'Scrub track expands from 8px to 12px; scrub thumb expands from 14px to 24px with 5px white halo', () => {
    // Check resting track height: 8px
    assert.match(componentsCss, /\.osd-progress-track\s*\{[\s\S]*?height:\s*8px;/, 'Resting track height must be 8px');

    // Check focused track height: 12px
    assert.match(componentsCss, /\.osd-progress-track:focus,[\s\S]*?\.osd-progress-track\.focused\s*\{[\s\S]*?height:\s*12px;/, 'Focused track height must be 12px');

    // Check resting thumb diameter: 14px
    assert.match(componentsCss, /\.osd-scrub-thumb\s*\{[\s\S]*?width:\s*14px;\s*height:\s*14px;/, 'Resting thumb diameter must be 14px');

    // Check focused thumb diameter: 24px
    assert.match(componentsCss, /\.osd-progress-track\.focused\s+\.osd-scrub-thumb[\s\S]*?width:\s*24px;\s*height:\s*24px;/, 'Focused thumb diameter must be 24px');

    // Check focused thumb halo box-shadow: 0 0 0 5px #FFFFFF, 0 0 24px rgba(149, 255, 80, 0.85)
    assert.match(componentsCss, /\.osd-progress-track\.focused\s+\.osd-scrub-thumb[\s\S]*?box-shadow:\s*0\s+0\s+0\s+5px\s+#FFFFFF,\s*0\s+0\s+24px\s+rgba\(149,\s*255,\s*80,\s*0\.85\);/i, 'Focused thumb must have 5px white halo and lime glow');
  });

  await check('TIMELINE_TABULAR_TYPOGRAPHY', 'Timeline time display utilizes Google Sans and font-variant-numeric: tabular-nums', () => {
    const timeMatch = componentsCss.match(/\.osd-time\s*\{([\s\S]*?)\}/);
    assert.ok(timeMatch, '.osd-time CSS block must exist');
    const block = timeMatch[1];

    assert.match(block, /font-variant-numeric:\s*tabular-nums;/, '.osd-time must declare tabular-nums');
    assert.match(block, /font-size:\s*20px;/, '.osd-time font-size must be 20px');
    assert.match(block, /font-weight:\s*500;/, '.osd-time font-weight must be 500');
  });

  // ===========================================================================
  // SUMMARY REPORT
  // ===========================================================================
  console.log(`\n${C.bold}${C.magenta}========================================================================${C.reset}`);
  console.log(`${C.bold}► EMPIRICAL ADVERSARIAL TEST SUMMARY: UI-M3${C.reset}`);
  console.log(`  ${C.gray}Total Checks Executed:${C.reset}  ${C.bold}${totalChecks}${C.reset}`);
  console.log(`  ${C.green}Passed Checks:${C.reset}          ${C.bold}${passedChecks}${C.reset}`);
  console.log(`  ${C.red}Failed Checks:${C.reset}          ${C.bold}${failedChecks}${C.reset}`);
  console.log(`${C.bold}${C.magenta}========================================================================${C.reset}\n`);

  if (failedChecks > 0) {
    console.error(`${C.red}CRITICAL DEFECTS FOUND: ${failedChecks} test(s) failed!${C.reset}`);
    failureList.forEach((f, idx) => {
      console.error(`  ${idx + 1}. ${f.label}\n     ${f.error}`);
    });
    process.exit(1);
  } else {
    console.log(`${C.bold}${C.green}VERDICT: APPROVE (ALL ${totalChecks} ADVERSARIAL VERIFICATION CHECKS PASSED 100%)${C.reset}\n`);
    process.exit(0);
  }
}

runAllAdversarialChallenges().catch(err => {
  console.error('Fatal crash during adversarial suite execution:', err);
  process.exit(1);
});

